def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def_total = 0
    my_def_total = 0
    for my, op in history:
        if op == 'D':
            opp_def_total += 1
        if my == 'D':
            my_def_total += 1

    last_my, last_opp = history[-1]

    if n == 99:
        return 'D'
    if n == 98:
        if opp_def_total > 0:
            recent_opp_def = 0
            for i in range(n - 5, n):
                if history[i][1] == 'D':
                    recent_opp_def += 1
            recent_my_def = 0
            for i in range(max(0, n - 4), n):
                if history[i][0] == 'D':
                    recent_my_def += 1
            if last_opp == 'D' or recent_opp_def >= 2 or recent_my_def > 0:
                return 'D'
            if opp_def_total * 2 > n:
                return 'D'
        return 'C'

    if opp_def_total == 0:
        return 'C'

    recent_len = min(n, 10)
    recent_opp_def = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    recent_def_rate = recent_opp_def / recent_len
    overall_def_rate = opp_def_total / n

    if recent_def_rate >= 0.5 or overall_def_rate >= 0.5:
        return 'D'

    retaliation_rate = 0.0
    if my_def_total > 0:
        retaliations = 0
        for i in range(n):
            if history[i][0] == 'D':
                if i + 1 < n and history[i + 1][1] == 'D':
                    retaliations += 1
        retaliation_rate = retaliations / my_def_total
        if retaliation_rate > 0.4:
            if last_opp == 'D':
                if overall_def_rate < 0.3:
                    return 'C'
                if recent_def_rate > 0.3:
                    return 'D'
                return 'C'
            return 'C'

    my_recent_def = 0
    for i in range(max(0, n - 4), n):
        if history[i][0] == 'D':
            my_recent_def += 1

    if retaliation_rate <= 0.4:
        if overall_def_rate > 0.3:
            return 'D'
        if overall_def_rate > 0.2:
            if n % 6 == 0 and my_recent_def == 0:
                return 'D'
        else:
            if n % 12 == 0 and my_recent_def == 0:
                return 'D'

    return 'C'
